using System;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;
// Persists authoring fields only. Does not serialize a running scene or clone live combat state.
[InitializeOnLoad]public static class CardLabConfigurationPersistence
{
 const string Key="CardLab.PendingConfiguration";
 [Serializable]public sealed class Box<T>{public T value;}
 [Serializable]public sealed class Reference{public string guid,scenePath,objectPath,type;public long localId;public int index;public bool isNull;}
 [Serializable]public sealed class Field{public string name,json;public bool references,isNull;public Reference[] objects;}
 [Serializable]public sealed class ComponentData{public string path,type;public int index;public List<Field> fields=new List<Field>();}
 [Serializable]public sealed class Snapshot{public string scene;public List<ComponentData> components=new List<ComponentData>();}
 static CardLabConfigurationPersistence(){CardLab.SaveConfigurationRequested+=Capture;EditorApplication.playModeStateChanged+=s=>{if(s==PlayModeStateChange.EnteredEditMode)EditorApplication.delayCall+=ApplyPending;};}
 static bool Supported(Type type){string name=type.Name;return name=="V06Card"||name=="V06Attack"||name=="V06Skills"||name=="RunStats"||name=="V09Elements"||name=="V09Build"||name=="EnemyAnimationProfile"||name=="ArenaPlayerAnimation"||name=="AnimationWorkbench"||name=="SwordChargeHud"||name=="SceneSkillHud"||name=="CardLab"||name=="ArenaActorAppearance"||name=="ArenaSkillAppearance"||name=="ArenaSkillAudio"||name=="ArenaAudioSettings"||name.EndsWith("Tuning");}
 static string PathOf(Transform t){var names=new List<string>();while(t){names.Insert(0,t.name);t=t.parent;}return string.Join("/",names.ToArray());}
 static int Index(Component component){var list=component.gameObject.GetComponents(component.GetType());return Array.IndexOf(list,component);}
 static bool Eligible(FieldInfo field,Type owner){if(field.IsStatic||field.IsInitOnly||field.IsNotSerialized)return false;if(!field.IsPublic&&!(owner.Name.EndsWith("Tuning")||owner==typeof(ArenaPlayerAnimation)))return false;if(!field.IsPublic&&!Attribute.IsDefined(field,typeof(SerializeField)))return false;if(typeof(Component).IsAssignableFrom(field.FieldType))return false;
 if(owner==typeof(CardLab)&&new List<string>{"loadoutResult","selectedCard","desiredLevel","placement","panelCollapsed"}.Contains(field.Name))return false;return true;}
 static Reference Ref(UnityEngine.Object obj){if(!obj)return new Reference{isNull=true};string guid;long id;if(AssetDatabase.TryGetGUIDAndLocalFileIdentifier(obj,out guid,out id)&&EditorUtility.IsPersistent(obj))return new Reference{guid=guid,localId=id};var go=obj as GameObject;var component=obj as Component;if(component)go=component.gameObject;if(go&&go.scene.IsValid())return new Reference{scenePath=go.scene.path,objectPath=PathOf(go.transform),type=component?component.GetType().AssemblyQualifiedName:null,index=component?Index(component):0};throw new InvalidOperationException("运行时生成的资源未保存为项目资产");}
 static object BoxValue(Type type,string json){var wrapper=typeof(Box<>).MakeGenericType(type);return wrapper.GetField("value").GetValue(JsonUtility.FromJson(json,wrapper));}
 public static void Capture(CardLab lab){if(!Application.isPlaying){if(!string.IsNullOrEmpty(SessionState.GetString(Key,"")))ApplyPending();else EditorSceneManager.SaveScene(lab.gameObject.scene);return;}var snapshot=new Snapshot{scene=lab.gameObject.scene.path};int skipped=0;
 foreach(var root in lab.gameObject.scene.GetRootGameObjects())foreach(var component in root.GetComponentsInChildren<MonoBehaviour>(true)){if(!component||!Supported(component.GetType()))continue;var data=new ComponentData{path=PathOf(component.transform),type=component.GetType().AssemblyQualifiedName,index=Index(component)};
 foreach(var field in component.GetType().GetFields(BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic)){if(!Eligible(field,component.GetType()))continue;try{var value=field.GetValue(component);var element=field.FieldType.IsArray?field.FieldType.GetElementType():field.FieldType;var record=new Field{name=field.Name};if(typeof(UnityEngine.Object).IsAssignableFrom(element)){if(typeof(Component).IsAssignableFrom(element))continue;record.references=true;record.isNull=value==null;var references=new List<Reference>();if(field.FieldType.IsArray){if(value!=null)foreach(var obj in (Array)value)references.Add(Ref((UnityEngine.Object)obj));}else references.Add(Ref((UnityEngine.Object)value));record.objects=references.ToArray();}else{var wrapper=typeof(Box<>).MakeGenericType(field.FieldType);var box=Activator.CreateInstance(wrapper);wrapper.GetField("value").SetValue(box,value);record.json=JsonUtility.ToJson(box);}data.fields.Add(record);}catch(Exception e){skipped++;Debug.LogWarning(component.name+"."+field.Name+" 未记录："+e.Message);}}
 snapshot.components.Add(data);}
 SessionState.SetString(Key,JsonUtility.ToJson(snapshot));SessionState.EraseString("CardLab.PendingRange.Scene");lab.SetConfigurationSaveMessage("已记录 "+snapshot.components.Count+" 个配置对象，退出Play后保存"+(skipped>0?"；部分临时资源已跳过，见Console":""));}
 static GameObject Find(UnityEngine.SceneManagement.Scene scene,string path){foreach(var root in scene.GetRootGameObjects()){if(path==root.name)return root;if(path.StartsWith(root.name+"/",StringComparison.Ordinal)){var child=root.transform.Find(path.Substring(root.name.Length+1));if(child)return child.gameObject;}}return null;}
 static UnityEngine.Object Resolve(Reference reference){if(reference==null||reference.isNull)return null;if(!string.IsNullOrEmpty(reference.guid)){string path=AssetDatabase.GUIDToAssetPath(reference.guid);foreach(var obj in AssetDatabase.LoadAllAssetsAtPath(path)){string guid;long id;if(AssetDatabase.TryGetGUIDAndLocalFileIdentifier(obj,out guid,out id)&&id==reference.localId)return obj;}throw new Exception("资源无法恢复："+path);}
 var scene=UnityEngine.SceneManagement.SceneManager.GetSceneByPath(reference.scenePath);var go=Find(scene,reference.objectPath);if(!go)throw new Exception("场景引用无法恢复："+reference.objectPath);if(string.IsNullOrEmpty(reference.type))return go;var all=go.GetComponents(Type.GetType(reference.type));return all[reference.index];}
 [MenuItem("Tools/Arena/应用待保存配置")]
 public static void ApplyPending(){string json=SessionState.GetString(Key,"");if(EditorApplication.isPlaying||string.IsNullOrEmpty(json))return;var snapshot=JsonUtility.FromJson<Snapshot>(json);var scene=UnityEngine.SceneManagement.SceneManager.GetSceneByPath(snapshot.scene);if(!scene.IsValid()||!scene.isLoaded){Debug.LogWarning("请打开 "+snapshot.scene+" 再应用待保存配置");return;}int applied=0;
 foreach(var data in snapshot.components){var go=Find(scene,data.path);var type=Type.GetType(data.type);if(!go||type==null){Debug.LogWarning("未覆盖已删除对象："+data.path);continue;}var components=go.GetComponents(type);if(data.index>=components.Length)continue;var component=components[data.index];Undo.RecordObject(component,"保存调试配置");foreach(var record in data.fields){var field=type.GetField(record.name,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic);if(field==null)continue;try{object value;if(record.references){if(record.isNull)value=null;else if(field.FieldType.IsArray){var array=Array.CreateInstance(field.FieldType.GetElementType(),record.objects.Length);for(int i=0;i<array.Length;i++)array.SetValue(Resolve(record.objects[i]),i);value=array;}else value=Resolve(record.objects[0]);}else value=BoxValue(field.FieldType,record.json);field.SetValue(component,value);}catch(Exception e){Debug.LogError("保存失败 "+data.path+"."+record.name+": "+e.Message);return;}}EditorUtility.SetDirty(component);applied++;}
 EditorSceneManager.MarkSceneDirty(scene);if(EditorSceneManager.SaveScene(scene)){SessionState.EraseString(Key);Debug.Log("已保存当前配置："+applied+" 个对象 → "+snapshot.scene);}}
}
